CREATE OR REPLACE VIEW public.posts_public WITH (security_invoker = true) AS SELECT id, user_id, title, description, category, price, latitude, longitude, image_urls, is_visible, created_at, updated_at, is_mobile, mobile_location_precise, live_latitude, live_longitude, live_updated_at, operating_hours FROM public.posts WHERE is_visible = true AND (NOT is_mobile OR public.mobile_service_on_duty(operating_hours)); GRANT SELECT ON public.posts_public TO anon, authenticated, service_role;